#include <stdio.h>
#include <stdlib.h>

int main() {
    // Stack: 자동 할당/해제
    int stackVar = 10;

    // Heap: 수동 할당
    int *heapVar = malloc(sizeof(int));
    *heapVar = 20;

    printf("Stack: %d, Heap: %d\n", stackVar, *heapVar);

    // Heap: 수동 해제 (필수!)
    free(heapVar);

    return 0;
}
